import{At as e,Mt as t,Qt as n,lt as r}from"./chunks/framework.DwOUwJQP.js";var i=JSON.parse(`{"title":"OIDC","description":"","frontmatter":{"title":"OIDC","date":"2022-01-09T15:13:14.000Z","tags":["protocol"]},"headers":[],"relativePath":"blogs/concept/protocol/oidc.md","filePath":"blogs/concept/protocol/oidc.md","lastUpdated":1787477097000}`),a={name:`blogs/concept/protocol/oidc.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<p>借鉴自：<a href="https://www.cnblogs.com/linianhui/p/openid-connect-core.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/linianhui/p/openid-connect-core.html</a></p><h4 id="_1、什么是oidc" tabindex="-1">1、什么是OIDC? <a class="header-anchor" href="#_1、什么是oidc" aria-label="Permalink to “1、什么是OIDC?”">​</a></h4><p>官方网址：<a href="https://openid.net/connect/" target="_blank" rel="noreferrer">https://openid.net/connect/</a></p><p>OIDC 是 OpenID Connect 的简称，OIDC=(Identity, Authentication) + OAuth2.0。它在OAuth2上构建了一个身份层，是一个基于OAuth2协议的身份认证标准协议。OAuth2是一个授权协议，它无法提供完善的身份认证功能，OIDC使用OAuth2的授权服务器来为第三方客户端提供用户的身份认证，并把对应的身份认证信息传递给客户端，且可以适用于各种类型的客户端（比如服务端应用，移动APP，JS应用），且完全兼容OAuth2，也就是说你搭建了一个OIDC的服务后，也可以当作一个OAuth2的服务来用。</p><h4 id="_2、oidc-协议族" tabindex="-1">2、OIDC 协议族 <a class="header-anchor" href="#_2、oidc-协议族" aria-label="Permalink to “2、OIDC 协议族”">​</a></h4><p>OIDC 本身是有多个规范构成，其中包含一个核心的规范，多个可选的规范来扩展支持</p><ol><li><a href="http://openid.net/specs/openid-connect-core-1_0.html" target="_blank" rel="noreferrer">Core</a>：必选。定义OIDC的核心功能，在OAuth 2.0之上构建身份认证，以及如何使用Claims来传递用户的信息。</li><li><a href="http://openid.net/specs/openid-connect-discovery-1_0.html" target="_blank" rel="noreferrer">Discovery</a>：可选。发现服务，使客户端可以动态的获取OIDC服务相关的元数据描述信息（比如支持那些规范，接口地址是什么等等）。</li><li><a href="http://openid.net/specs/openid-connect-registration-1_0.html" target="_blank" rel="noreferrer">Dynamic Registration</a> ：可选。动态注册服务，使客户端可以动态的注册到OIDC的OP（这个缩写后面会解释）。</li><li><a href="http://openid.net/specs/oauth-v2-multiple-response-types-1_0.html" target="_blank" rel="noreferrer">OAuth 2.0 Multiple Response Types</a> ：可选。针对OAuth2的扩展，提供几个新的response_type。</li><li><a href="http://openid.net/specs/oauth-v2-form-post-response-mode-1_0.html" target="_blank" rel="noreferrer">OAuth 2.0 Form Post Response Mode</a>：可选。针对OAuth2的扩展，OAuth2回传信息给客户端是通过URL的querystring和fragment这两种方式，这个扩展标准提供了一基于form表单的形式把数据post给客户端的机制。</li><li><a href="http://openid.net/specs/openid-connect-session-1_0.html" target="_blank" rel="noreferrer">Session Management</a> ：可选。Session管理，用于规范OIDC服务如何管理Session信息。</li><li><a href="http://openid.net/specs/openid-connect-frontchannel-1_0.html" target="_blank" rel="noreferrer">Front-Channel Logout</a>：可选。基于前端的注销机制，使得RP（这个缩写后面会解释）可以不使用OP的iframe来退出。</li><li><a href="http://openid.net/specs/openid-connect-backchannel-1_0.html" target="_blank" rel="noreferrer">Back-Channel Logout</a>：可选。基于后端的注销机制，定义了RP和OP直接如何通信来完成注销。</li></ol><h4 id="_3、oidc-核心概念" tabindex="-1">3、OIDC 核心概念 <a class="header-anchor" href="#_3、oidc-核心概念" aria-label="Permalink to “3、OIDC 核心概念”">​</a></h4><p>OAuth2 提供了 Access Token 来解决授权第三方客户端访问受保护资源的问题；OIDC 在这个基础上提供了 ID Token来解决第三方客户端标识用户身份认证的问题。OIDC的核心在于在OAuth2的授权流程中，一并提供用户的身份认证信息（ID Token）给到第三方客户端，ID Token使用JWT格式来包装，得益于JWT（<a href="http://www.cnblogs.com/linianhui/p/oauth2-extensions-protocol-and-json-web-token.html#auto_id_6" target="_blank" rel="noreferrer">JSON Web Token</a>）的自包含性，紧凑性以及防篡改机制，使得ID Token可以安全的传递给第三方客户端程序并且容易被验证。此外还提供了UserInfo的接口，用户获取用户的更完整的信息。</p><h5 id="_3-1-oidc-主要术语" tabindex="-1">3.1 OIDC 主要术语 <a class="header-anchor" href="#_3-1-oidc-主要术语" aria-label="Permalink to “3.1 OIDC 主要术语”">​</a></h5><p>主要的术语以及概念介绍（完整术语参见<a href="http://openid.net/specs/openid-connect-core-1_0.html#Terminology%EF%BC%89" target="_blank" rel="noreferrer">http://openid.net/specs/openid-connect-core-1_0.html#Terminology）</a></p><ol><li>EU（End User）：一个人类用户</li><li>RP（Relying Party）：用来代指OAuth2中的受信任的客户端，身份认证和授权信息的消费方</li><li>OP（OpenID Provider）：有能力提供EU认证的服务（比如OAuth2中的授权服务），用来为RP提供EU的身份认证信息</li><li>ID Token：JWT格式的数据，包含EU身份认证的信息</li><li>UserInfo Endpoint：用户信息接口（受OAuth2保护），当RP使用Access Token访问时，返回授权用户信息，此接口必须使用HTTPS</li></ol><h5 id="_3-2-oidc-工作流程" tabindex="-1">3.2 OIDC 工作流程 <a class="header-anchor" href="#_3-2-oidc-工作流程" aria-label="Permalink to “3.2 OIDC 工作流程”">​</a></h5><p>从抽象的角度来看，OIDC的流程由以下5个步骤构成</p><ol><li>RP发送一个认证请求给OP</li><li>OP对EU进行身份认证，然后提供授权</li><li>OP把ID Token和AccessToken（需要的话）返回给RP</li><li>RP使用AccessToken发送一个请求UserInfo Endpoint</li><li>UserInfo Endpoint返回EU的Claims</li></ol><h5 id="_3-3-id-token" tabindex="-1">3.3 ID Token <a class="header-anchor" href="#_3-3-id-token" aria-label="Permalink to “3.3 ID Token”">​</a></h5><p><strong>OIDC对OAuth2最主要的扩展就是提供了ID Token。</strong> ID Token是一个安全令牌，是一个授权服务器提供的包含 <strong>用户信息（由一组Cliams构成以及其它辅助的Cliams）</strong> 的JWT格式的数据结构。ID Token的主要构成部分如下（使用OAuth2流程的OIDC）</p><ol><li>【必须】iss=Issuer Identifier。提供给认证信息者的唯一标识，一般是一个https的url（不包含querystring和fragment部分）</li><li>【必须】sub=Subject Identity。iss提供的EU的标识，在iss范围内唯一。它会被RP用来标识唯一的用户。最长为255个ASCII个字符</li><li>【必须】aud=Audience(s)。标识ID Token的受众。必须包含OAuth2的client_id。</li><li>【必须】exp=Expiration time。过期时间，超过此时间的ID Token会作废不再被验证通过。</li><li>【必须】iat=Issued At Time。JWT的构建的时间</li><li>auth_time=AuthencationTime：EU完成认证的时间。如果RP发送的认证请求携带max_age的参数，则此Claim是必须的</li><li>【可选】acr = Authentication Context Class Reference。表示一个认证上下文引用值，可以用来标识认证上下文类。</li><li>【可选】amr = Authentication Methods References。表示一组认证方法。</li><li>【可选】azp = Authorized party。结合aud使用。只有在被认证的一方和受众（aud）不一致时才使用此值，一般情况下很少使用。</li></ol><p>ID Token通常情况下还会包含其他的Claims（毕竟上述claim中只有sub是和EU相关的，这在一般情况下是不够的，必须还需要EU的用户名，头像等其他的资料，OIDC提供了一组公共的cliams，请移步这里<a href="http://openid.net/specs/openid-connect-core-1_0.html#StandardClaims%EF%BC%89%E3%80%82%E5%8F%A6%E5%A4%96ID" target="_blank" rel="noreferrer">http://openid.net/specs/openid-connect-core-1_0.html#StandardClaims）。另外ID</a> Token必须使用JWS进行签名和JWE加密，从而提供认证的完整性、不可否认性以及可选的保密性。一个ID Token的例子如下：</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;iss&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://server.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;sub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;24400320&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;aud&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;s6BhdRkqt3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;nonce&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;n-0S6_WzA2Mj&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;exp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1311281970</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;iat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1311280970</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;auth_time&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1311280969</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;acr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;urn:mace:incommon:iap:silver&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   }</span></span></code></pre></div><h5 id="_3-4-认证" tabindex="-1">3.4 认证 <a class="header-anchor" href="#_3-4-认证" aria-label="Permalink to “3.4 认证”">​</a></h5><p>OIDC的认证流程主要是由OAuth2的几种授权流程延伸而来的，有以下三种：</p><ol><li>Authorization Code Flow：使用Oauth2的授权码来换取Id Token和Access Token。</li><li>Implicit Flow：使用OAuth2的Implicit流程获取Id Token和Access Token。</li><li>Hybrid Flow：混合Authorization Code Flow+Implici Flow。</li></ol><h6 id="_3-4-1-基于authorization-code的认证请求" tabindex="-1">3.4.1 基于Authorization Code的认证请求 <a class="header-anchor" href="#_3-4-1-基于authorization-code的认证请求" aria-label="Permalink to “3.4.1 基于Authorization Code的认证请求”">​</a></h6><p>这种方式使用OAuth2的Authorization Code的方式来完成用户身份认证，所有的Token都是通过Token EndPoint（OAuth2中定义：<a href="https://tools.ietf.org/html/rfc6749#section-3.2%EF%BC%89%E6%9D%A5%E5%8F%91%E6%94%BE%E7%9A%84%E3%80%82%E6%9E%84%E5%BB%BA%E4%B8%80%E4%B8%AAOIDC%E7%9A%84Authentication" target="_blank" rel="noreferrer">https://tools.ietf.org/html/rfc6749#section-3.2）来发放的。构建一个OIDC的Authentication</a> Request需要提供如下的参数：</p><ol><li>scope：必须。OIDC的请求必须包含值为“openId”的scope参数</li><li>response_type：必选。同OAuth2。</li><li>client_id：必选。同OAuth2。</li><li>redirect_uri：必选。同OAuth2。</li><li>state：推荐。同OAuth2。防止CSRF, XSRF。</li></ol><p>以上这5个参数是和OAuth2相同的。除此之外，还定义了如下的参数：</p><ol><li>response_mode：可选。OIDC新定义的参数（<a href="http://openid.net/specs/oauth-v2-form-post-response-mode-1_0.html" target="_blank" rel="noreferrer">OAuth 2.0 Form Post Response Mode</a>），用来指定Authorization Endpoint以何种方式返回数据。</li><li>nonce：可选。ID Token中的出现的nonce就是来源于此。</li><li>display ： 可选。指示授权服务器呈现怎样的界面给EU。有效值有（page，popup，touch，wap），其中默认是page。page=普通的页面，popup=弹出框，touch=支持触控的页面，wap=移动端页面。</li><li>prompt：可选。这个参数允许传递多个值，使用空格分隔。用来指示授权服务器是否引导EU重新认证和同意授权（consent，就是EU完成身份认证后的确认同意授权的页面）。有效值有（none，login，consent，select_account）。none=不实现现任何认证和确认同意授权的页面，如果没有认证授权过，则返回错误login_required或interaction_required。login=重新引导EU进行身份认证，即使已经登录。consent=重新引导EU确认同意授权。select_account=假如EU在授权服务器有多个账号的话，允许EU选择一个账号进行认证。</li><li>max_age：可选。代表EU认证信息的有效时间，对应ID Token中auth_time的claim。比如设定是20分钟，则超过了时间，则需要引导EU重新认证。</li><li>ui_locales：可选。用户界面的本地化语言设置项。</li><li>id_token_hint：可选。之前发放的ID Token，如果ID Token经过验证且是有效的，则需要返回一个正常的响应；如果有误，则返回对应的错误提示。</li><li>login_hint：可选。向授权服务器提示登录标识符，EU可能会使用它登录(如果需要的话)。比如指定使用用户使用blackheart账号登录，当然EU也可以使用其他账号登录，这只是类似html中input元素的placeholder。</li><li>acr_values：可选。Authentication Context Class Reference values，对应ID Token中的acr的Claim。此参数允许多个值出现，使用空格分割。</li></ol><p>以上是基于Authorization Code方式的OIDC的认证请求所需的参数。在OIDC的其他认证流程中也会有其他的参数或不同的参数值（稍有差异）。一个简单的示例如下：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /authorize?</span></span>
<span class="line"><span>    response_type=code</span></span>
<span class="line"><span>    &amp;scope=openid%20profile%20email</span></span>
<span class="line"><span>    &amp;client_id=s6BhdRkqt3</span></span>
<span class="line"><span>    &amp;state=af0ifjsldkj</span></span>
<span class="line"><span>    &amp;redirect_uri=https%3A%2F%2Fclient.example.org%2Fcb HTTP/1.1</span></span>
<span class="line"><span>  Host: server.example.com</span></span></code></pre></div><p>也可以是一个基于302的重定向方式。</p><h6 id="_3-4-2-基于-authorization-code的认证请求的响应" tabindex="-1">3.4.2 基于 Authorization Code的认证请求的响应 <a class="header-anchor" href="#_3-4-2-基于-authorization-code的认证请求的响应" aria-label="Permalink to “3.4.2 基于 Authorization Code的认证请求的响应”">​</a></h6><p>在授权服务器接收到认证请求之后，需要对请求参数做严格的验证，具体的规则参见<a href="http://openid.net/specs/openid-connect-core-1_0.html#AuthRequestValidation%EF%BC%8C%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%E5%90%8E%E5%BC%95%E5%AF%BCEU%E8%BF%9B%E8%A1%8C%E8%BA%AB%E4%BB%BD%E8%AE%A4%E8%AF%81%E5%B9%B6%E4%B8%94%E5%90%8C%E6%84%8F%E6%8E%88%E6%9D%83%E3%80%82%E5%9C%A8%E8%BF%99%E4%B8%80%E5%88%87%E9%83%BD%E5%AE%8C%E6%88%90%E5%90%8E%EF%BC%8C%E4%BC%9A%E9%87%8D%E5%AE%9A%E5%90%91%E5%88%B0RP%E6%8C%87%E5%AE%9A%E7%9A%84%E5%9B%9E%E8%B0%83%E5%9C%B0%E5%9D%80%EF%BC%8C%E5%B9%B6%E4%B8%94%E6%8A%8Acode%E5%92%8Cstate%E5%8F%82%E6%95%B0%E4%BC%A0%E9%80%92%E8%BF%87%E5%8E%BB%E3%80%82%E6%AF%94%E5%A6%82%EF%BC%9A" target="_blank" rel="noreferrer">http://openid.net/specs/openid-connect-core-1_0.html#AuthRequestValidation，验证通过后引导EU进行身份认证并且同意授权。在这一切都完成后，会重定向到RP指定的回调地址，并且把code和state参数传递过去。比如：</a></p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> HTTP/1.1 302 Found</span></span>
<span class="line"><span>  Location: https://client.example.org/cb?</span></span>
<span class="line"><span>    code=SplxlOBeZQQYbYS6WxSbIA</span></span>
<span class="line"><span>    &amp;state=af0ifjsldkj</span></span></code></pre></div><h6 id="_3-4-3-获取id-token" tabindex="-1">3.4.3 获取ID Token <a class="header-anchor" href="#_3-4-3-获取id-token" aria-label="Permalink to “3.4.3 获取ID Token”">​</a></h6><p>RP使用上一步获得的code来请求Token EndPoint，这一步同OAuth2，就不再展开细说了。然后Token EndPoint会返回响应的Token，其中除了OAuth2规定的部分数据外，还会附加一个<strong>id_token</strong>的字段。id_token字段就是上面提到的ID Token。例如：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>  Content-Type: application/json</span></span>
<span class="line"><span>  Cache-Control: no-store</span></span>
<span class="line"><span>  Pragma: no-cache</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>   &quot;access_token&quot;: &quot;SlAV32hkKG&quot;,</span></span>
<span class="line"><span>   &quot;token_type&quot;: &quot;Bearer&quot;,</span></span>
<span class="line"><span>   &quot;refresh_token&quot;: &quot;8xLOxBtZp8&quot;,</span></span>
<span class="line"><span>   &quot;expires_in&quot;: 3600,</span></span>
<span class="line"><span>   &quot;id_token&quot;: &quot;eyJhbGciOiJSUzI1NiIsImtpZCI6IjFlOWdkazcifQ.ewogImlzc</span></span>
<span class="line"><span>     yI6ICJodHRwOi8vc2VydmVyLmV4YW1wbGUuY29tIiwKICJzdWIiOiAiMjQ4Mjg5</span></span>
<span class="line"><span>     NzYxMDAxIiwKICJhdWQiOiAiczZCaGRSa3F0MyIsCiAibm9uY2UiOiAibi0wUzZ</span></span>
<span class="line"><span>     fV3pBMk1qIiwKICJleHAiOiAxMzExMjgxOTcwLAogImlhdCI6IDEzMTEyODA5Nz</span></span>
<span class="line"><span>     AKfQ.ggW8hZ1EuVLuxNuuIJKX_V8a_OMXzR0EHR9R6jgdqrOOF4daGU96Sr_P6q</span></span>
<span class="line"><span>     Jp6IcmD3HP99Obi1PRs-cwh3LO-p146waJ8IhehcwL7F09JdijmBqkvPeB2T9CJ</span></span>
<span class="line"><span>     NqeGpe-gccMg4vfKjkM8FcGvnzZUN4_KSP0aAp1tOJ1zZwgjxqGByKHiOtX7Tpd</span></span>
<span class="line"><span>     QyHE5lcMiKPXfEIQILVq0pc_E2DzL7emopWoaoZTF_m0_N0YzFC6g6EJbOEoRoS</span></span>
<span class="line"><span>     K5hoDalrcvRYLSrQAZZKflyuVCyixEoV9GfNQC3_osjzw2PAithfubEEBLuVVk4</span></span>
<span class="line"><span>     XUVrWOLrLl0nx7RkKU8NXNHq-rvKMzqg&quot;</span></span>
<span class="line"><span>  }</span></span></code></pre></div><p>其中看起来一堆乱码的部分就是JWT格式的ID Token。在RP拿到这些信息之后，需要对id_token以及access_token进行验证（具体的规则参见<a href="http://openid.net/specs/openid-connect-core-1_0.html#IDTokenValidation%E5%92%8Chttp://openid.net/specs/openid-connect-core-1_0.html#ImplicitTokenValidation%EF%BC%89%E3%80%82%E8%87%B3%E6%AD%A4%EF%BC%8C%E5%8F%AF%E4%BB%A5%E8%AF%B4%E7%94%A8%E6%88%B7%E8%BA%AB%E4%BB%BD%E8%AE%A4%E8%AF%81%E5%B0%B1%E5%8F%AF%E4%BB%A5%E5%AE%8C%E6%88%90%E4%BA%86%EF%BC%8C%E5%90%8E%E7%BB%AD%E5%8F%AF%E4%BB%A5%E6%A0%B9%E6%8D%AEUserInfo" target="_blank" rel="noreferrer">http://openid.net/specs/openid-connect-core-1_0.html#IDTokenValidation和http://openid.net/specs/openid-connect-core-1_0.html#ImplicitTokenValidation）。至此，可以说用户身份认证就可以完成了，后续可以根据UserInfo</a> EndPoint获取更完整的信息。</p><h6 id="_3-4-4-implicit-flow和hybrid-flow" tabindex="-1">3.4.4 Implicit Flow和Hybrid Flow <a class="header-anchor" href="#_3-4-4-implicit-flow和hybrid-flow" aria-label="Permalink to “3.4.4 Implicit Flow和Hybrid Flow”">​</a></h6><p>Implicit Flow的工作方式是在OAuth2 Implicit Flow上附加提供id_token，当然，认证请求的参数和基于Authorization Code的流程稍有不同，具体的差异参见<a href="http://openid.net/specs/openid-connect-core-1_0.html#ImplicitAuthRequest%EF%BC%8C%E8%BF%99%E9%87%8C%E5%B0%B1%E4%B8%8D%E5%81%9A%E8%AF%A6%E7%BB%86%E4%BB%8B%E7%BB%8D%E4%BA%86%E3%80%82" target="_blank" rel="noreferrer">http://openid.net/specs/openid-connect-core-1_0.html#ImplicitAuthRequest，这里就不做详细介绍了。</a></p><p>Hybrid Flow则=Authorization Code Flow+Implicit Flow，也不再详细介绍了。</p><h5 id="_3-5-userinfo-endpoint" tabindex="-1">3.5 UserInfo Endpoint <a class="header-anchor" href="#_3-5-userinfo-endpoint" aria-label="Permalink to “3.5 UserInfo Endpoint”">​</a></h5><p>UserIndo EndPoint是一个受OAuth2保护的资源。在RP得到Access Token后可以请求此资源，然后获得一组EU相关的Claims，这些信息可以说是ID Token的扩展，比如如果你觉得ID Token中只需包含EU的唯一标识sub即可（避免ID Token过于庞大），然后通过此接口获取完整的EU的信息。此资源必须部署在TLS之上，例如：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  GET /userinfo HTTP/1.1</span></span>
<span class="line"><span>  Host: server.example.com</span></span>
<span class="line"><span>  Authorization: Bearer SlAV32hkKG</span></span></code></pre></div><p>成功之后响应如下</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> HTTP/1.1 200 OK</span></span>
<span class="line"><span>  Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>   &quot;sub&quot;: &quot;248289761001&quot;,</span></span>
<span class="line"><span>   &quot;name&quot;: &quot;Jane Doe&quot;,</span></span>
<span class="line"><span>   &quot;given_name&quot;: &quot;Jane&quot;,</span></span>
<span class="line"><span>   &quot;family_name&quot;: &quot;Doe&quot;,</span></span>
<span class="line"><span>   &quot;preferred_username&quot;: &quot;j.doe&quot;,</span></span>
<span class="line"><span>   &quot;email&quot;: &quot;janedoe@example.com&quot;,</span></span>
<span class="line"><span>   &quot;picture&quot;: &quot;http://example.com/janedoe/me.jpg&quot;</span></span>
<span class="line"><span>  }</span></span></code></pre></div><p>其中sub代表EU的唯一标识，这个claim是必须的，其他的都是可选的。</p><h4 id="_4、总结" tabindex="-1">4、总结 <a class="header-anchor" href="#_4、总结" aria-label="Permalink to “4、总结”">​</a></h4><p>继OAuth2之后，感觉OIDC也要大放异彩了。其本身是一个完全开放的标准，而且兼容众多的已有的IDP（身份提供商），比如基于SAML的、基于WS-Federation的等等已有的身份认证系统，都可以作为OIDC的OP存在。总结一下OIDC有那些特性和好处吧：</p><ol><li>OIDC使得身份认证可以作为一个服务存在。</li><li>OIDC可以很方便的实现SSO（跨顶级域）。</li><li>OIDC兼容OAuth2，可以使用Access Token控制受保护的API资源。</li><li>OIDC可以兼容众多的IDP作为OIDC的OP来使用。</li><li>OIDC的一些敏感接口均强制要求TLS，除此之外，得益于JWT,JWS,JWE家族的安全机制，使得一些敏感信息可以进行数字签名、加密和验证，进一步确保整个认证过程中的安全保障</li></ol>`,50)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};